<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';
ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');
session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';
function archiveH(string|int|null $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;
if(!is_array($user)||($user['role']??'')!=='coach'){http_response_code(403);exit('Das Auftragsarchiv ist Coaches vorbehalten.');}
$db=coachingDatabase();$coach=(int)$user['id'];$orderId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
if($orderId<1){http_response_code(400);exit('Ungültiger Auftrag.');}
$q=$db->prepare("SELECT a.*,k.vorname,k.nachname,k.id AS client_id FROM coaching_auftraege a INNER JOIN klienten k ON k.id=a.klient_id WHERE a.id=:id AND a.coach_benutzer_id=:coach AND k.benutzer_id=:owner AND a.status='abgeschlossen' LIMIT 1");
$q->execute(['id'=>$orderId,'coach'=>$coach,'owner'=>$coach]);$order=$q->fetch(PDO::FETCH_ASSOC);
if(!$order){http_response_code(404);exit('Archivierter Auftrag nicht gefunden.');}
$clientId=(int)$order['client_id'];
$q=$db->prepare('SELECT id,beginn,dauer_minuten,format,status FROM termine WHERE klient_id=:client AND auftrag_id=:order ORDER BY beginn DESC');$q->execute(['client'=>$clientId,'order'=>$orderId]);$appointments=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT id,titel,inhalt,erstellt_am,termin_id,skala_vorher,skala_nachher FROM coaching_sitzungsnotizen WHERE klient_id=:client AND auftrag_id=:order AND coach_benutzer_id=:coach ORDER BY erstellt_am DESC');$q->execute(['client'=>$clientId,'order'=>$orderId,'coach'=>$coach]);$notes=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT titel,beschreibung,erfolgskriterium,zieltermin,status FROM coaching_ziele WHERE klient_id=:client AND auftrag_id=:order AND coach_benutzer_id=:coach ORDER BY geaendert_am DESC');$q->execute(['client'=>$clientId,'order'=>$orderId,'coach'=>$coach]);$goals=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT titel,beschreibung,faellig_am,status,klient_sichtbar FROM coaching_aufgaben WHERE klient_id=:client AND auftrag_id=:order AND coach_benutzer_id=:coach ORDER BY faellig_am IS NULL,faellig_am');$q->execute(['client'=>$clientId,'order'=>$orderId,'coach'=>$coach]);$tasks=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT id,autor_rolle,inhalt,erstellt_am FROM coaching_nachrichten WHERE klient_id=:client AND auftrag_id=:order AND coach_benutzer_id=:coach ORDER BY id');$q->execute(['client'=>$clientId,'order'=>$orderId,'coach'=>$coach]);$messages=$q->fetchAll(PDO::FETCH_ASSOC);$messageFiles=[];
$q=$db->prepare('SELECT f.id,f.nachricht_id,f.originalname FROM coaching_nachrichten_dateien f INNER JOIN coaching_nachrichten n ON n.id=f.nachricht_id WHERE n.klient_id=:client AND n.auftrag_id=:order AND n.coach_benutzer_id=:coach');$q->execute(['client'=>$clientId,'order'=>$orderId,'coach'=>$coach]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $file)$messageFiles[(int)$file['nachricht_id']][]=$file;
$q=$db->prepare('SELECT id,titel,status,vorlage_version,zugewiesen_am FROM coaching_klientendokumente WHERE klient_id=:client AND auftrag_id=:order AND coach_benutzer_id=:coach ORDER BY zugewiesen_am DESC');$q->execute(['client'=>$clientId,'order'=>$orderId,'coach'=>$coach]);$documents=$q->fetchAll(PDO::FETCH_ASSOC);$documentFiles=[];
$q=$db->prepare('SELECT f.id,f.klientendokument_id,f.version,f.originalname FROM coaching_dokumentdateien f INNER JOIN coaching_klientendokumente d ON d.id=f.klientendokument_id WHERE d.klient_id=:client AND d.auftrag_id=:order AND d.coach_benutzer_id=:coach ORDER BY f.hochgeladen_am DESC');$q->execute(['client'=>$clientId,'order'=>$orderId,'coach'=>$coach]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $file)$documentFiles[(int)$file['klientendokument_id']][]=$file;
$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auftragsarchiv</title><link rel="stylesheet" href="assets/layout.css"><style>
.page{max-width:1180px;margin:auto;padding:34px clamp(24px,4vw,58px) 62px}.card{background:#fff;border:1px solid #e4ebe6;border-radius:14px;padding:20px;margin:16px 0}.row{border-top:1px solid #edf1ee;padding:13px 0}.meta{color:#708078;font-size:13px;white-space:pre-wrap}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#edf5ef;color:#245c50;font-size:12px}.notice{padding:12px;background:#fff8e8;border-radius:9px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.button{display:inline-block;background:#245c50;color:#fff;text-decoration:none;border-radius:9px;padding:10px 14px}@media(max-width:800px){.grid{grid-template-columns:1fr}}
</style></head><body class="has-app-sidebar"><?php require_once dirname(__DIR__).'/app/navigation.php';renderCoachingSidebar($user,'engagements',$token);?><main class="page">
<p><a href="client-overview.php?id=<?=$clientId?>">← Zur Klientenakte</a></p><h1>Auftragsarchiv: <?=archiveH($order['titel'])?></h1><p><?=archiveH($order['vorname'].' '.$order['nachname'])?> · abgeschlossen <?=archiveH($order['abgeschlossen_am']?date('d.m.Y',strtotime($order['abgeschlossen_am'])):'')?></p>
<div class="notice">Archivansicht für den Coach. Private Coach-Notizen sind hier sichtbar und werden niemals im Coachee-Portal angezeigt.<?=((int)$order['archiv_freigegeben']===1)?' Der Coachee hat ebenfalls Zugriff auf die freigegebenen Inhalte.':' Der Coachee hat keinen Zugriff auf dieses Archiv.'?></div>
<div class="grid"><section class="card"><h2>Sitzungen (<?=count($appointments)?>)</h2><?php foreach($appointments as $item):?><div class="row"><strong><?=archiveH(date('d.m.Y H:i',strtotime($item['beginn'])))?></strong> <span class="badge"><?=archiveH($item['status'])?></span><div class="meta"><?=archiveH($item['format'])?> · <?=archiveH($item['dauer_minuten'])?> Min.</div></div><?php endforeach;?></section>
<section class="card"><h2>Private Coach-Notizen (<?=count($notes)?>)</h2><?php foreach($notes as $note):?><div class="row"><strong><?=archiveH($note['titel'])?></strong><div class="meta"><?=archiveH(date('d.m.Y H:i',strtotime($note['erstellt_am'])))?><?= $note['skala_vorher']!==null&&$note['skala_nachher']!==null?' · Skala '.archiveH($note['skala_vorher']).' → '.archiveH($note['skala_nachher']):'' ?><br><?=archiveH($note['inhalt'])?></div></div><?php endforeach;?></section>
<section class="card"><h2>Ziele (<?=count($goals)?>)</h2><?php foreach($goals as $goal):?><div class="row"><strong><?=archiveH($goal['titel'])?></strong> <span class="badge"><?=archiveH($goal['status'])?></span><div class="meta"><?=archiveH($goal['beschreibung']??'')?><?= $goal['erfolgskriterium']?' · Erfolg: '.archiveH($goal['erfolgskriterium']):''?></div></div><?php endforeach;?></section>
<section class="card"><h2>Aufgaben (<?=count($tasks)?>)</h2><?php foreach($tasks as $task):?><div class="row"><strong><?=archiveH($task['titel'])?></strong> <span class="badge"><?=archiveH($task['status'])?></span><div class="meta"><?=archiveH($task['beschreibung']??'')?><?= $task['faellig_am']?' · Fällig '.archiveH(date('d.m.Y',strtotime($task['faellig_am']))):'' ?></div></div><?php endforeach;?></section>
<section class="card"><h2>Nachrichten (<?=count($messages)?>)</h2><?php foreach($messages as $message):?><div class="row"><strong><?=$message['autor_rolle']==='coach'?'Coach':'Coachee'?> · <?=archiveH(date('d.m.Y H:i',strtotime($message['erstellt_am'])))?></strong><div class="meta"><?=archiveH($message['inhalt'])?></div><?php foreach($messageFiles[(int)$message['id']]??[] as $file):?><div><a href="message-download.php?id=<?=(int)$file['id']?>"><?=archiveH($file['originalname'])?> herunterladen</a></div><?php endforeach;?></div><?php endforeach;?></section>
<section class="card"><h2>Dokumente (<?=count($documents)?>)</h2><?php foreach($documents as $document):?><div class="row"><strong><?=archiveH($document['titel'])?></strong> <span class="badge"><?=archiveH($document['status'])?></span><div class="meta">zugewiesen <?=archiveH(date('d.m.Y',strtotime($document['zugewiesen_am'])))?> · <a href="document-download.php?type=assigned-template&amp;id=<?=(int)$document['id']?>">Vorlage öffnen</a></div><?php foreach($documentFiles[(int)$document['id']]??[] as $file):?><div class="meta">Rücklauf v<?=(int)$file['version']?> · <?=archiveH($file['originalname'])?> · <a href="document-download.php?type=return&amp;id=<?=(int)$file['id']?>">Ansehen</a></div><?php endforeach;?></div><?php endforeach;?></section></div>
<p><a class="button" href="engagements.php">Aufträge verwalten</a></p></main></body></html>